<script setup lang="ts">
import { onMounted,onUnmounted,ref,watch } from 'vue';
import * as echarts from 'echarts/core';
import {LineChart} from 'echarts/charts';
import {GridComponent,TooltipComponent,DataZoomComponent,LegendComponent} from 'echarts/components';
import {CanvasRenderer} from 'echarts/renderers';
import {theme} from '@/lib/theme';
import type {MetricsSample} from '@/api';
echarts.use([LineChart,GridComponent,TooltipComponent,DataZoomComponent,LegendComponent,CanvasRenderer]);
const props=defineProps<{samples:Partial<MetricsSample>[];mode:'percent'|'network'|'cpu'}>();
const el=ref<HTMLElement>();let chart:echarts.ECharts|undefined;let ro:ResizeObserver|undefined;let mo:MutationObserver|undefined;
function paint(){if(!chart)return;const dark=document.documentElement.classList.contains('dark');const fg=dark?'#b7c9c2':'#607572';const narrow=(el.value?.clientWidth??600)<400;const mini=props.mode==='cpu',network=props.mode==='network';const defs=mini?[['CPU','#17977a','cpu_pct']]:network?[['下行','#17977a','rx_bps'],['上行','#d49443','tx_bps']]:[['CPU','#17977a','cpu_pct'],['内存','#39a8b3','memory'],['磁盘','#d49443','disk']];chart.setOption({animation:false,grid:mini?{left:0,right:0,top:2,bottom:2}:{left:45,right:18,top:34,bottom:props.samples.length>120?65:28},tooltip:{show:!mini,trigger:'axis',confine:true,renderMode:'richText'},legend:{show:!mini,textStyle:{color:fg},top:0},xAxis:{type:'time',show:!mini,splitNumber:narrow?2:5,axisLabel:{color:fg,fontSize:10,hideOverlap:true},splitLine:{show:false},axisLine:{lineStyle:{color:'#88888830'}}},yAxis:{type:'value',show:!mini,min:network?undefined:0,max:network?undefined:100,axisLabel:{color:fg,fontSize:10,formatter:network?(v:number)=>v>=1048576?(v/1048576).toFixed(0)+'M':(v/1024).toFixed(0)+'K':(v:number)=>v+'%'},splitLine:{lineStyle:{color:'#88888820'}}},dataZoom:!mini&&props.samples.length>120?[{type:'inside',filterMode:'none'},{type:'slider',height:18,bottom:8}]:undefined,series:defs.map(([name,color,key])=>({name,type:'line',showSymbol:props.samples.length<2&&!mini,symbolSize:6,connectNulls:false,lineStyle:{width:2,color},itemStyle:{color},areaStyle:mini?{color,opacity:.06}:undefined,data:props.samples.map(sample=>{let value:number|null|undefined;if(key==='memory')value=sample.mem_total_kb?(sample.mem_total_kb-(sample.mem_avail_kb??0))/sample.mem_total_kb*100:null;else if(key==='disk')value=sample.disk_total_kb?(sample.disk_used_kb??0)/sample.disk_total_kb*100:null;else value=(sample as Record<string,number|null|undefined>)[key];return [(sample.at??0)*1000,typeof value==='number'&&Number.isFinite(value)?value:null]})}))},true)}
watch(()=>[props.samples,props.mode,theme.value],()=>setTimeout(paint,0),{deep:true});onMounted(()=>{if(!el.value)return;chart=echarts.init(el.value,undefined,{renderer:'canvas'});ro=new ResizeObserver(()=>{chart?.resize();paint()});ro.observe(el.value);mo=new MutationObserver(paint);mo.observe(document.documentElement,{attributes:true,attributeFilter:['class']});paint()});onUnmounted(()=>{ro?.disconnect();mo?.disconnect();chart?.dispose()});
</script>
<template><div class="chart-wrapper" :class="{'mini-chart':mode==='cpu'}"><div ref="el" class="metric-chart" role="img" :aria-label="mode==='cpu'?'实时 CPU 趋势':mode==='network'?'历史上下行网络流量图表':'历史 CPU 内存磁盘使用率图表'"/><p v-if="!samples.length&&mode!=='cpu'" class="chart-empty">所选周期暂无记录；服务器会每分钟自动采样，无需保持网页打开。</p></div></template>
